assert_columns "rooms" "capacity:NO;id:NO;name:NO"
assert_type "rooms" "capacity" "integer"
assert_type "rooms" "id" "integer"
assert_type "rooms" "name" "text"
assert_columns "courses" "code:NO;ends_on:NO;fee:NO;id:NO;room_id:NO;starts_on:NO;title:NO"
assert_type "courses" "code" "text"
assert_type "courses" "ends_on" "date"
assert_type "courses" "fee" "money"
assert_type "courses" "id" "integer"
assert_type "courses" "room_id" "integer"
assert_type "courses" "starts_on" "date"
assert_type "courses" "title" "text"
assert_columns "participants" "email:NO;full_name:NO;id:NO;phone:YES"
assert_type "participants" "email" "text"
assert_type "participants" "full_name" "text"
assert_type "participants" "id" "integer"
assert_type "participants" "phone" "text"
assert_columns "enrollments" "course_id:NO;enrolled_on:NO;participant_id:NO"
assert_type "enrollments" "course_id" "integer"
assert_type "enrollments" "enrolled_on" "date"
assert_type "enrollments" "participant_id" "integer"
assert_equals "rooms generates identifiers with auto increment" "SELECT EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='rooms' AND COLUMN_NAME='id'" "auto_increment"
assert_equals "courses generates identifiers with auto increment" "SELECT EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='courses' AND COLUMN_NAME='id'" "auto_increment"
assert_equals "participants generates identifiers with auto increment" "SELECT EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='participants' AND COLUMN_NAME='id'" "auto_increment"
# Test descriptions are in English. SQL assertions use the isolated test database.
assert_equals "rooms has the required primary key" "SELECT GROUP_CONCAT(COLUMN_NAME ORDER BY ORDINAL_POSITION) FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='rooms' AND CONSTRAINT_NAME='PRIMARY'" "id"
assert_equals "courses has the required primary key" "SELECT GROUP_CONCAT(COLUMN_NAME ORDER BY ORDINAL_POSITION) FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='courses' AND CONSTRAINT_NAME='PRIMARY'" "id"
assert_equals "participants has the required primary key" "SELECT GROUP_CONCAT(COLUMN_NAME ORDER BY ORDINAL_POSITION) FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='participants' AND CONSTRAINT_NAME='PRIMARY'" "id"
assert_equals "enrollments has the required primary key" "SELECT GROUP_CONCAT(COLUMN_NAME ORDER BY COLUMN_NAME) FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='enrollments' AND CONSTRAINT_NAME='PRIMARY'" "course_id,participant_id"
assert_equals "enrollments has an index on course_id,enrolled_on" "SELECT COUNT(*) FROM (SELECT INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='enrollments'  GROUP BY INDEX_NAME HAVING GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX)='course_id,enrolled_on') AS matching_indexes" "1"
assert_accepts "Rooms and participants receive generated identifiers" "INSERT INTO rooms(name,capacity) VALUES('Aula A',20); INSERT INTO participants(email,full_name) VALUES('anna@example.test','Anna')"
assert_accepts "A course accepts consistent dates and a default fee" "INSERT INTO courses(code,title,room_id,starts_on,ends_on) VALUES('SQL-01','SQL',1,'2026-11-01','2026-11-02')"
assert_equals "The default fee is zero" "SELECT fee=0 FROM courses WHERE id=1" "1"
assert_accepts "A participant can enroll" "INSERT INTO enrollments VALUES(1,1,'2026-10-23')"
assert_rejects "A duplicate enrollment is rejected" "1062" "INSERT INTO enrollments VALUES(1,1,'2026-10-24')"
assert_rejects "Unknown courses are rejected" "1452" "INSERT INTO enrollments VALUES(99,1,'2026-10-23')"
assert_rejects "Unknown participants are rejected" "1452" "INSERT INTO enrollments VALUES(1,99,'2026-10-23')"
assert_rejects "Room capacity must be positive" "3819" "INSERT INTO rooms(name,capacity) VALUES('B',0)"
assert_rejects "Room names must be unique" "1062" "INSERT INTO rooms(name,capacity) VALUES('Aula A',10)"
assert_rejects "Participant emails must be unique" "1062" "INSERT INTO participants(email,full_name) VALUES('anna@example.test','Altra Anna')"
assert_rejects "Course codes must be unique" "1062" "INSERT INTO courses(code,title,room_id,starts_on,ends_on) VALUES('SQL-01','Altro',1,'2026-11-01','2026-11-02')"
assert_rejects "Course end cannot precede its start" "3819" "INSERT INTO courses(code,title,room_id,starts_on,ends_on) VALUES('SQL-02','SQL',1,'2026-11-02','2026-11-01')"
assert_rejects "Course fees cannot be negative" "3819|1264" "UPDATE courses SET fee=-1 WHERE id=1"
assert_rejects "Courses require a valid room" "1452" "UPDATE courses SET room_id=99 WHERE id=1"
assert_rejects "Occupied rooms cannot be deleted" "1451" "DELETE FROM rooms WHERE id=1"
assert_rejects "Referenced courses cannot be deleted" "1451" "DELETE FROM courses WHERE id=1"
assert_rejects "Enrolled participants cannot be deleted" "1451" "DELETE FROM participants WHERE id=1"
